select cron.schedule('learn-vision-every-10min','*/10 * * * *', $$select net.http_post(url:='https://oicqtpjjwmgsiluvkmpu.supabase.co/functions/v1/ads-manager', headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',(select value from public.app_secrets where key='ads_cron_secret')), body:='{"action":"learn_vision","limit":4}'::jsonb, timeout_milliseconds:=150000)$$);
